import{_ as n,o as a,c as o,af as r}from"./chunks/framework.B28LkSoM.js";const p=JSON.parse('{"title":"LangChain概述与生态","description":"为什么需要 LangChain、v0.3 到 v1.2 的架构演进，以及 LangChain/LangGraph/Deep Agent/LangSmith 四大支柱","frontmatter":{"title":"LangChain概述与生态","published":"2026-09-21T00:00:00.000Z","description":"为什么需要 LangChain、v0.3 到 v1.2 的架构演进，以及 LangChain/LangGraph/Deep Agent/LangSmith 四大支柱","tags":["LangChain","AI"],"image":"https://img.tsh520.cn/file/blog/post-covers/langchain-01-overview-ecosystem.webp","order":1,"date":"2026-09-21T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/LangChain学习笔记/01-LangChain概述与生态.md","filePath":"posts/学习文档/LangChain学习笔记/01-LangChain概述与生态.md"}'),g={name:"posts/学习文档/LangChain学习笔记/01-LangChain概述与生态.md"};function s(e,t,i,l,h,d){return a(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1789948800000"},[...t[0]||(t[0]=[r('<h2 id="为什么需要-langchain" tabindex="-1">为什么需要 LangChain <a class="header-anchor" href="#为什么需要-langchain" aria-label="Permalink to &quot;为什么需要 LangChain&quot;">​</a></h2><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p001-%E4%BB%8E%E4%BC%A0%E7%BB%9F%E5%BA%94%E7%94%A8%E5%88%B0%E6%99%BA%E8%83%BD%E4%BD%93%E6%97%B6%E4%BB%A3.jpg" alt=""><em>图：从 PC 互联网时代、移动互联网时代一路走到 AI 智能化时代，应用形态的演进取向</em></p><h3 id="应用形态的三次跃迁" tabindex="-1">应用形态的三次跃迁 <a class="header-anchor" href="#应用形态的三次跃迁" aria-label="Permalink to &quot;应用形态的三次跃迁&quot;">​</a></h3><p>课程开篇用一条一路上扬的曲线，把&quot;从传统应用到智能体&quot;的演进串了起来，三个时代依次是：</p><table tabindex="0"><thead><tr><th>时代</th><th>应用形态</th></tr></thead><tbody><tr><td>PC 互联网时代</td><td>传统应用</td></tr><tr><td>移动互联网时代</td><td>移动应用</td></tr><tr><td>AI 智能化时代</td><td><strong>智能体（Agent）</strong></td></tr></tbody></table><p>曲线之所以上扬，是因为每跃迁一次，应用能做的事就上了一个台阶，一直到 AI 智能化时代，应用形态变成会自己规划、自己调用工具、自己动手完成的<strong>智能体</strong>。这就是本节标题的完整含义——<strong>从传统应用到智能体时代</strong>，也是&quot;为什么需要 LangChain&quot;这个问题的起点：要造智能体，光有一个大模型是不够的。</p><h3 id="单一的大模型有局限" tabindex="-1">单一的大模型有局限 <a class="header-anchor" href="#单一的大模型有局限" aria-label="Permalink to &quot;单一的大模型有局限&quot;">​</a></h3><p>一个大模型自己做不到这些事：</p><ul><li><strong>没有实时数据</strong>：训练数据是&quot;冻结&quot;的，问&quot;现在的热门影片&quot;它答不准</li><li><strong>会幻觉</strong>：遇到训练时没学过的内容，它会编造答案</li><li><strong>不能操作外部系统</strong>：查数据库、调 API、读文件都不行</li><li><strong>没有记忆</strong>：每次对话都是独立的（第 3 章学过：模型是无状态的）</li></ul><p>所以要构建真正实用的 AI 应用，必须把大模型与<strong>外部工具、数据源和记忆机制</strong>有机结合——这正是 LangChain 要解决的问题。</p><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p001-%E5%A4%A7%E6%A8%A1%E5%9E%8B%E4%B8%89%E5%A4%A7%E5%B1%80%E9%99%90.jpg" alt=""><em>图：单一的大语言模型的三大局限——知识受训练数据限制、无法直接与外部系统交互、不具备状态保持能力</em></p><h3 id="langchain-的定位" tabindex="-1">LangChain 的定位 <a class="header-anchor" href="#langchain-的定位" aria-label="Permalink to &quot;LangChain 的定位&quot;">​</a></h3><p>LangChain 是大模型与应用之间的<strong>中间层</strong>，可统一调用各类大模型、管理提示词与上下文，还能集成外部工具和数据源。核心定位三点：</p><ol><li><strong>打通大模型与外部资源</strong>：统一接口对接数据库、检索引擎、API、文件系统等</li><li><strong>封装底层复杂逻辑</strong>：抽象工具调用、记忆等能力，降低智能体开发难度</li><li><strong>支撑多智能体协作</strong>：依托 LangGraph 等生态，从单智能体拓展至多智能体协作</li></ol><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p002-%E6%A1%86%E6%9E%B6%E5%AE%9A%E4%BD%8D%E4%B8%89%E5%B1%82%E7%BB%93%E6%9E%84.jpg" alt=""><em>图：LangChain 作为大模型与应用之间的中间层——对上统一调用各类大模型，对下连接数据库、检索引擎、API、文件系统</em></p><h3 id="课程对定位的完整表述" tabindex="-1">课程对定位的完整表述 <a class="header-anchor" href="#课程对定位的完整表述" aria-label="Permalink to &quot;课程对定位的完整表述&quot;">​</a></h3><p>上面三点是压缩后的版本，课程里还有几句更完整的说法：</p><ul><li><strong>LangChain，是当前构建生产级 AI 智能体系统的首选。</strong></li><li>完整表述：LangChain 作为大模型与应用间的中间层，可统一调用各类大模型、管理提示词与上下文，还能集成外部工具和数据源，<strong>快速搭建具备推理、行动能力的智能体</strong>。</li><li>第 3 点&quot;支撑多智能体协作&quot;的完整说法：依托 LangGraph 等生态，从单智能体拓展至多智能体协作，<strong>可构建工业级智能体</strong>。</li></ul><h3 id="六类典型应用场景" tabindex="-1">六类典型应用场景 <a class="header-anchor" href="#六类典型应用场景" aria-label="Permalink to &quot;六类典型应用场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>解决什么痛点</th><th>怎么做</th></tr></thead><tbody><tr><td>检索增强生成（RAG）</td><td>知识滞后、幻觉</td><td>检索外部知识库并向量化，让模型基于最新资料回答</td></tr><tr><td>Agent 智能体</td><td>LLM 无法直接执行复杂任务</td><td>把模型当&quot;推理引擎&quot;，自主规划并调用外部工具</td></tr><tr><td>对话系统与聊天机器人</td><td>多轮对话的&quot;记忆&quot;流失</td><td>集成记忆管理，记住用户偏好和历史交互</td></tr><tr><td>多模态应用</td><td>只有文本</td><td>融合图像识别、语音转文字等能力</td></tr><tr><td>自动化写作与格式化生成</td><td>格式不标准、质量不稳定</td><td>配合提示词模板与输出解析器</td></tr><tr><td>数据连接与结构化处理</td><td>非结构化数据难利用</td><td>从 PDF/Excel 提取信息、自然语言转 SQL</td></tr></tbody></table><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p002-%E5%B9%BF%E6%B3%9B%E9%80%82%E7%94%A8%E6%A0%B8%E5%BF%83%E5%9C%BA%E6%99%AF.jpg" alt=""><em>图：LangChain 广泛适用的六大核心场景全景——RAG、Agent 智能体、对话机器人、多模态、内容生成、数据连接与处理</em></p><h3 id="六类场景的完整表述-课程原文" tabindex="-1">六类场景的完整表述（课程原文） <a class="header-anchor" href="#六类场景的完整表述-课程原文" aria-label="Permalink to &quot;六类场景的完整表述（课程原文）&quot;">​</a></h3><p>上表是压缩版，课程对六大场景的完整说法是&quot;<strong>痛点 + 功能</strong>&quot;成对给出的：</p><ol><li><strong>检索增强生成（RAG）</strong>——<strong>痛点</strong>：解决大模型知识滞后（无实时数据）和幻觉问题；<strong>功能</strong>：检索外部知识库（文档 / 数据库）并向量化，让模型基于最新、最相关的资料回答。</li><li><strong>Agent 智能体构建</strong>——<strong>痛点</strong>：解决 LLM 无法直接执行复杂任务的问题；<strong>功能</strong>：将模型作为&quot;推理引擎&quot;，自主规划路径并动态调用外部工具（如订票、查报告、写 SQL），实现复杂任务。</li><li><strong>对话系统与聊天机器人</strong>——<strong>痛点</strong>：解决多轮对话中的&quot;记忆&quot;流失问题；<strong>功能</strong>：集成记忆管理系统，记住用户偏好和历史交互，并结合**私有数据（如教育教材、订单库）**提供专业服务。</li><li><strong>多模态应用开发</strong>——<strong>痛点</strong>：跨越单一文本交互的限制；<strong>功能</strong>：融合图像识别、语音转文字等技术，让模型具备处理音视频和图片的综合推理能力。</li><li><strong>自动化写作与格式化生成</strong>——<strong>痛点</strong>：解决生成内容格式不标准、质量不稳定的问题；<strong>功能</strong>：配合提示词模板（Templates）与输出解析器（Parsers），自动产出规范的报告、合同或邮件。</li><li><strong>数据连接与结构化处理</strong>——<strong>痛点</strong>：解决非结构化数据难以被模型直接利用的问题；<strong>功能</strong>：<strong>强大的数据连接能力使大模型能够与各种数据源和结构化数据交互</strong>——比如从 PDF、Excel 中提取关键信息，或实现自然语言与 SQL 的自动转换。</li></ol><h2 id="大模型相关岗位介绍" tabindex="-1">大模型相关岗位介绍 <a class="header-anchor" href="#大模型相关岗位介绍" aria-label="Permalink to &quot;大模型相关岗位介绍&quot;">​</a></h2><p>课程给的判断很直接：<strong>应用开发是大模型最值得关注的方向——应用为王！</strong> 学习 LangChain 框架，就是为了高效开发大模型应用。</p><h3 id="五层技术栈与对应岗位" tabindex="-1">五层技术栈与对应岗位 <a class="header-anchor" href="#五层技术栈与对应岗位" aria-label="Permalink to &quot;五层技术栈与对应岗位&quot;">​</a></h3><p>整个&quot;AI 大模型与 Agent 应用开发&quot;的架构可以分成五层，每层都对应一类岗位：</p><table tabindex="0"><thead><tr><th>层</th><th>层里有什么</th><th>对应岗位</th></tr></thead><tbody><tr><td><strong>应用与（Agent）层</strong></td><td><strong>B 端应用</strong>：智能制造、智能客服、在线诊疗……；<strong>C 端应用</strong>：AI 翻译、AI 问答、文生图/视频……；<strong>G 端应用</strong>：城市大脑、智慧交通、在线业务；<strong>AI 智能体（Agent）</strong>：代码助手（Coding Agent）、自动化工作流、简历筛选助手</td><td><strong>大模型与 Agent 应用开发工程师</strong></td></tr><tr><td><strong>行业/多模态应用大模型层</strong></td><td>行业大模型：制造、医疗、金融、电商；多模态模型：文本、图像、音频、视频</td><td>大模型微调 / 算法工程师</td></tr><tr><td><strong>通用大模型（Foundation Models）层</strong></td><td>通用大模型：文心一言、通义千问、ChatGPT、豆包；LLM 推理引擎：Ollama、localAI</td><td>大模型基座开发 / 优化工程师</td></tr><tr><td><strong>海量数据与治理层</strong></td><td>结构化 / 非结构化数据；数据处理 / 清洗 / 标注（Postman 数据接口）</td><td>数据开发 / 清洗工程师</td></tr><tr><td><strong>算力与 Infra 基础设施层</strong></td><td>算力：GPU / NPU 数据中心；Infra 平台：K8s、Docker、Dify 部署</td><td>大模型运维、Infra 工程师</td></tr></tbody></table><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p003-%E5%A4%A7%E6%A8%A1%E5%9E%8B%E4%BA%94%E5%B1%82%E6%9E%B6%E6%9E%84%E4%B8%8E%E5%B2%97%E4%BD%8D%E6%98%A0%E5%B0%84.jpg" alt=""><em>图：AI 大模型与 Agent 应用开发的完整架构与岗位映射——从底层的算力与 Infra、海量数据与治理，往上是 Model Foundation、行业/多模态应用大模型，最上面是应用与（Agent）层</em></p><h3 id="agents-编排与控制" tabindex="-1">Agents 编排与控制 <a class="header-anchor" href="#agents-编排与控制" aria-label="Permalink to &quot;Agents 编排与控制&quot;">​</a></h3><p>应用与 Agent 层里还有一块独立的&quot;<strong>Agents 编排与控制</strong>&quot;，列出的三样东西正好是这门课后面要一路学下去的工具：</p><ul><li><strong>LangChain 流程图</strong>：把任务串成流程</li><li><strong>LangGraph 状态机</strong>：需要状态、分支、循环的复杂编排</li><li><strong>多 Agent 协作系统（Multi-Agent System）</strong>：多个智能体分工协作</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>看清楚这张图的位置关系就明白了：越往上层越贴近业务，而&quot;应用与 Agent 层&quot;正是这门课的主线——LangChain（流程图）→ LangGraph（状态机）→ 多 Agent 协作系统。</p></div><h2 id="langchain-是什么" tabindex="-1">LangChain 是什么 <a class="header-anchor" href="#langchain-是什么" aria-label="Permalink to &quot;LangChain 是什么&quot;">​</a></h2><h3 id="发展时间线-五个阶段" tabindex="-1">发展时间线（五个阶段） <a class="header-anchor" href="#发展时间线-五个阶段" aria-label="Permalink to &quot;发展时间线（五个阶段）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>标志</th></tr></thead><tbody><tr><td>诞生</td><td>2022-10</td><td>Harrison Chase 创建；名字来自 <strong>Language + Chain</strong>（链接语言模型与各类资源）</td></tr><tr><td>探索期</td><td>2022Q4–2023Q1</td><td>初版聚焦 PromptTemplate、LLMChain，社区迅速走红</td></tr><tr><td>体系化</td><td>2023Q2–Q4</td><td>引入 Tool、Agent、Retrieval；推出 LangChain Hub 与 LangSmith</td></tr><tr><td>平台化</td><td>2024–2025 上半年</td><td>LangGraph 与 LangServe 发布，从框架走向平台</td></tr><tr><td>深层智能体</td><td>2025 下半年至今</td><td>推出 Deep Agent（定位 Agent Harness，智能体执行框架）</td></tr></tbody></table><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p004-%E7%A4%BE%E5%8C%BA%E6%98%9F%E6%A0%87%E5%A2%9E%E9%95%BF%E6%9B%B2%E7%BA%BF.jpg" alt=""><em>图：LangChain 在 GitHub 上的 Star 增长曲线——从 2022 年开源起一路攀升到 12 万以上</em></p><h3 id="时间线的阶段细节" tabindex="-1">时间线的阶段细节 <a class="header-anchor" href="#时间线的阶段细节" aria-label="Permalink to &quot;时间线的阶段细节&quot;">​</a></h3><p>上表每格只有一句话，课程对五个阶段还有更完整的描述，几处细节值得记：</p><ul><li><strong>诞生（2022-10）</strong>：Harrison Chase（<strong>哈里森·蔡斯</strong>）当时的身份是<strong>哈佛大学的机器学习项目工程师</strong>；名字取自 <strong>Language</strong>（语言模型）与 <strong>Chain</strong>（链式连接），体现的核心设计理念是&quot;链接大语言模型与其他各种计算资源和数据，构建强大的 AI 应用&quot;。</li><li><strong>探索期（2022Q4–2023Q1）</strong>：凭前瞻性设计在开源社区迅速走红，<strong>GitHub Star 数快速破万</strong>，成为早期最受关注的大模型应用框架。</li><li><strong>体系化（2023Q2–Q4）</strong>：引入 Tool、Agent、Retrieval，形成 <strong>&quot;大模型 + 工具调用 + 记忆&quot;</strong> 的核心架构；同期推出 LangChain Hub 与 LangSmith，<strong>初步构建了从开发、调试到部署的生态闭环</strong>。</li><li><strong>平台化（2024–2025 上半年）</strong>：LangGraph 为<strong>工作流管理提供了有向图基础</strong>，LangServe 则<strong>解决了服务化部署的难题</strong>——至此生态完成从&quot;开发框架&quot;到&quot;智能体平台&quot;的跃升。</li><li><strong>深层智能体（2025 下半年至今）</strong>：Deep Agent 官方定位为 <strong>Agent Harness（智能体执行框架）</strong>，运行在 LangGraph 与 LangChain 之上，标志着生态进入新阶段——让开发者可构建基于多智能体的复杂化智能体系统。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>五个阶段的关键词连起来就是一条主线：<strong>框架</strong>（PromptTemplate / LLMChain）→ <strong>体系</strong>（Tool / Agent / Retrieval + Hub / LangSmith）→ <strong>平台</strong>（LangGraph / LangServe）→ <strong>多智能体</strong>（Deep Agent）。</p></div><h3 id="两个重要版本-v0-3-的痛与-v1-x-的重构" tabindex="-1">两个重要版本：v0.3 的痛与 v1.x 的重构 <a class="header-anchor" href="#两个重要版本-v0-3-的痛与-v1-x-的重构" aria-label="Permalink to &quot;两个重要版本：v0.3 的痛与 v1.x 的重构&quot;">​</a></h3><p>LangChain 长期因 API 变动频繁被戏称为&quot;版本碎钞机&quot;。2024 年起团队把链和智能体标记为弃用，转向基于 LangGraph 的统一智能体抽象；同时 GPT-4 之后&quot;工具调用、结构化输出、系统提示词&quot;都成了模型自带能力，再包一层显得多此一举——<strong>这一阶段开发者大规模流失</strong>。</p><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p005-%E6%A1%86%E6%9E%B6%E9%97%AE%E9%A2%98%E8%AF%8A%E6%96%AD%E4%B8%89%E7%97%9B%E7%82%B9.jpg" alt=""><em>图：LangChain 框架被吐槽的三大问题——文档混乱且更新滞后、抽象过度导致调试困难、版本不兼容</em></p><p>2025-10-20 发布 <strong>LangChain v1.0.0 + LangGraph v1.0.0</strong>，是里程碑事件：官方首次明确 <strong>API 稳定保证（2.0 前无破坏性变更）</strong>。</p><table tabindex="0"><thead><tr><th>维度</th><th>v0.3（过渡版）</th><th><strong>v1.2（生产级稳定版）</strong></th></tr></thead><tbody><tr><td>核心架构</td><td>以&quot;链（Chain）&quot;为核心</td><td>从&quot;链式调用&quot;转向<strong>智能体框架</strong></td></tr><tr><td>Agent 构建</td><td><code>initialize_agent</code> 等旧 API + AgentExecutor</td><td>官方标准入口 <strong><code>create_agent</code></strong>，底层基于 LangGraph</td></tr><tr><td>工具定义</td><td><code>@tool</code> / Tool 类，类型安全较弱</td><td>支持 <strong>Pydantic Schema</strong> 定义工具，类型安全</td></tr><tr><td>结构化输出</td><td>JSON Parser + 正则，稳定性差</td><td><strong>一等公民</strong>，直接绑定 Pydantic 类，由模型底层保证</td></tr><tr><td>输出解析</td><td>纯文本 + 手动解析</td><td>标准化 <code>content_blocks</code>（推理/文本/工具调用统一为对象）</td></tr><tr><td>扩展机制</td><td>缺乏系统性扩展方式</td><td><strong>Middleware 中间件</strong>系统，可拦截各生命周期</td></tr><tr><td>异步性能</td><td>一般</td><td>优化后响应速度提升 30%+</td></tr><tr><td>包结构</td><td>较混乱、耦合高</td><td>主 <code>langchain</code> 包保持轻量，旧功能迁至 <code>langchain-classic</code></td></tr><tr><td>Python 要求</td><td>&gt;= 3.9</td><td><strong>&gt;= 3.10</strong></td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">重要</p><p>学习与新建项目<strong>一律用 v1.x</strong>（本课程就是 1.2）。看到网上老教程里的 <code>initialize_agent</code>、<code>LLMChain</code>、<code>AgentExecutor</code>，要知道那是 v0.3 的写法，在 1.x 里已经移除或迁到 <code>langchain-classic</code>。</p></div><h3 id="版本对比补全-多模态、包结构与推荐用途" tabindex="-1">版本对比补全：多模态、包结构与推荐用途 <a class="header-anchor" href="#版本对比补全-多模态、包结构与推荐用途" aria-label="Permalink to &quot;版本对比补全：多模态、包结构与推荐用途&quot;">​</a></h3><p>上表之外，课程对比表里还有三个维度：</p><table tabindex="0"><thead><tr><th>维度</th><th>v0.3</th><th><strong>v1.2</strong></th></tr></thead><tbody><tr><td>多模态支持</td><td>支持不完善，<strong>无法无缝集成图像、音频</strong>等多模态数据</td><td><strong>完善了多模态适配</strong>，可轻松实现多模态对话、多模态 RAG 等功能</td></tr><tr><td>包结构与依赖</td><td>包结构相对混乱、各模块耦合度较高；<code>langchain</code> 包为直接依赖；内部从 <strong>Pydantic v1 升级到 v2</strong>，对依赖版本要求更严格</td><td>包结构清晰，主 <code>langchain</code> 包保持轻量，旧功能（如 Chains）被迁移至 <code>langchain-classic</code>；<strong><code>@langchain/core</code> 作为对等依赖</strong>，版本管理更灵活</td></tr><tr><td>推荐用途</td><td>只适用于<strong>维护依赖 v0.3 的老旧项目</strong>，不推荐用于新项目开发</td><td><strong>所有新项目和学习 LangChain 的首选版本</strong>；官方承诺 1.x 版本系列不会引入破坏性变更，保证了长期稳定性</td></tr></tbody></table><p>而 v1.0 发布这件事，课程还补了一条背景：<strong>发布同期完成 1.2 亿美元融资，估值超 12 亿美元</strong>，印证其作为 AI 基础设施的战略价值。</p><h3 id="v1-2-的主要模块" tabindex="-1">v1.2 的主要模块 <a class="header-anchor" href="#v1-2-的主要模块" aria-label="Permalink to &quot;v1.2 的主要模块&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包</th><th>作用</th></tr></thead><tbody><tr><td><code>langchain-core</code></td><td>核心 API：Runnable、BaseMessage 等</td></tr><tr><td><code>langchain</code></td><td>主包（轻量）：<code>create_agent</code>、<code>init_chat_model</code> 等</td></tr><tr><td><code>langchain-classic</code></td><td>冗余/不推荐使用的经典 API（0.x 常用、1.x 移除的都在这）</td></tr><tr><td><code>langchain-community</code></td><td>第三方集成（合作伙伴包如 langchain-openai、langchain-anthropic，按需安装）</td></tr><tr><td><code>langgraph</code></td><td>深度整合 LangGraph 1.0，协调多个 Chain/Agent/Tools，支持循环调用</td></tr></tbody></table><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p007-%E6%A0%B8%E5%BF%83%E5%8C%85%E6%9C%80%E5%B0%8F%E5%8C%96%E4%B8%8E%E4%BE%9B%E5%BA%94%E5%95%86%E6%8B%86%E5%88%86.jpg" alt=""><em>图：v1.2 的包结构——核心包最小化，langchain-core 只保留核心抽象接口，模型供应商与旧 API 各自拆成独立包</em></p><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>官方原话的意思：<strong>不要试图学完 LangChain 的所有 API</strong>，那是不可能的。搞懂核心逻辑与核心模块，其它用到再查——把它当<strong>工具箱</strong>，不是教科书。</p></div><p>文档地址：</p><ul><li>中文文档：<a href="https://docs.langchain.org.cn/oss/python/langchain/overview" target="_blank" rel="noreferrer">https://docs.langchain.org.cn/oss/python/langchain/overview</a></li><li>英文文档：<a href="https://docs.langchain.com/oss/python/langchain/overview" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/python/langchain/overview</a></li><li>API 查询（最常查）：<a href="https://reference.langchain.com/python/langchain/" target="_blank" rel="noreferrer">https://reference.langchain.com/python/langchain/</a></li></ul><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p008-API%E6%96%87%E6%A1%A3%E9%A1%B5%E9%9D%A2%E6%88%AA%E5%9B%BE.jpg" alt=""><em>图：API 文档查询页——LangChain、LangChain Core、LangChain Classic 等模块的接口都在这里查</em></p><h3 id="官网与-github-组织" tabindex="-1">官网与 GitHub 组织 <a class="header-anchor" href="#官网与-github-组织" aria-label="Permalink to &quot;官网与 GitHub 组织&quot;">​</a></h3><p>文档之前，课程先给了生态的两个总入口：</p><ul><li>官网：<a href="https://www.langchain.com/" target="_blank" rel="noreferrer">https://www.langchain.com/</a></li><li>GitHub 组织：<a href="https://github.com/langchain-ai" target="_blank" rel="noreferrer">https://github.com/langchain-ai</a></li></ul><h2 id="langchain-家族四大支柱" tabindex="-1">LangChain 家族四大支柱 <a class="header-anchor" href="#langchain-家族四大支柱" aria-label="Permalink to &quot;LangChain 家族四大支柱&quot;">​</a></h2><p>截至 2025-11，LangChain 已从一个框架成长为覆盖智能体全生命周期的技术生态，四大支柱分别对应四个层次：</p><table tabindex="0"><thead><tr><th>支柱</th><th>层次</th><th>一句话</th></tr></thead><tbody><tr><td><strong>LangChain</strong></td><td>基础能力层</td><td>智能体开发的基石（模型调用、工具与中间件集成、智能体构建）</td></tr><tr><td><strong>LangGraph</strong></td><td>运行时编排层</td><td>复杂工作流的编排引擎（把智能体抽象成有向图）</td></tr><tr><td><strong>Deep Agent</strong></td><td>智能体抽象层</td><td>智能体执行框架（Agent Harness），自带规划/文件系统/子智能体</td></tr><tr><td><strong>LangSmith</strong></td><td>监控与评估层</td><td>可视化监控与测试平台（追踪调用链路）</td></tr></tbody></table><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p009-%E7%94%9F%E6%80%81%E5%85%A8%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%E5%9B%9B%E5%B1%82.jpg" alt=""><em>图：LangChain 生态的四层结构——智能体抽象层（Deep Agent）、运行时编排层（LangGraph）、基础能力层（LangChain）、监控与评估层（LangSmith）</em></p><h3 id="官方文档入口" tabindex="-1">官方文档入口 <a class="header-anchor" href="#官方文档入口" aria-label="Permalink to &quot;官方文档入口&quot;">​</a></h3><ul><li>官方对四大支柱的解释：<a href="https://docs.langchain.com/oss/python/concepts/products" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/python/concepts/products</a></li><li>官方文档（三者对比，LangChain / LangGraph / Deep Agents 怎么选）：<a href="https://docs.langchain.com/oss/python/langchain/overview" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/python/langchain/overview</a></li></ul><h3 id="langchain-智能体开发的基石" tabindex="-1">LangChain：智能体开发的基石 <a class="header-anchor" href="#langchain-智能体开发的基石" aria-label="Permalink to &quot;LangChain：智能体开发的基石&quot;">​</a></h3><p>LangChain 是整个生态的<strong>核心与起点</strong>，为开发者提供模型调用、工具与中间件集成、智能体构建等一整套基础能力。其核心价值有三条：</p><ol><li><strong>统一的模型抽象层</strong>：屏蔽不同模型服务提供商（OpenAI、Anthropic、Ollama 等）的接口差异，提供一致的调用方式。</li><li><strong>高度模块化的设计</strong>：用 Message、Tool、Agent、Middleware 等组件实现灵活的组合与扩展。</li><li><strong>丰富的集成生态</strong>：预置了丰富的数据源、API、中间件等，构成强大的 AI 能力枢纽。</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>在整体架构中，<strong>LangChain 如同智能体的操作系统内核</strong>，是所有上层能力构建的基础。 课程给出的结论：<strong>如果你需要构建简单的智能体应用、无需复杂的编排需求，那就选择 LangChain。</strong></p></div><h3 id="langgraph-把智能体变成一张图" tabindex="-1">LangGraph：把智能体变成一张图 <a class="header-anchor" href="#langgraph-把智能体变成一张图" aria-label="Permalink to &quot;LangGraph：把智能体变成一张图&quot;">​</a></h3><p>把智能体内部抽象为一张<strong>有向图</strong>：</p><ul><li><strong>节点（Node）</strong>：代表独立的功能单元或决策点</li><li><strong>边（Edge）</strong>：定义节点之间的流转条件与路径</li><li><strong>状态（State）</strong>：共享上下文，在节点间传递并持久化</li></ul><p>通俗理解：<strong>LangChain = 能力抽象层（有什么能力）</strong>，<strong>LangGraph = 执行与编排层（怎么跑）</strong>。官方强调&quot;快速起步用 LangChain，复杂控制用 LangGraph，二者并行协同&quot;。</p><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p010-%E8%83%BD%E5%8A%9B%E5%B1%82%E4%B8%8E%E7%BC%96%E6%8E%92%E5%B1%82%E5%88%86%E5%B7%A5.jpg" alt=""><em>图：两层分工——LangChain 提供标准能力（有什么能力），LangGraph 用状态机、工作流与多 Agent 系统负责&quot;怎么跑&quot;</em></p><h3 id="图式结构带来了什么" tabindex="-1">图式结构带来了什么 <a class="header-anchor" href="#图式结构带来了什么" aria-label="Permalink to &quot;图式结构带来了什么&quot;">​</a></h3><p>课程对 LangGraph 的这个卖点有一句原话：<strong>通过这种图式结构，LangGraph 让智能体的工作流节点交互变得显式、可控、可观测。</strong></p><p>对比一下就明白了：链式调用是一条道走到黑，而图有节点、有边、有状态——节点之间的路径写在代码里看得见（<strong>显式</strong>），分支与循环都能表达（<strong>可控</strong>，LangGraph 还支持循环调用），每一步的共享状态也都留得下（<strong>可观测</strong>）。任务一旦从&quot;一条指令&quot;变成&quot;多步骤、有状态&quot;，这三样就是刚需。</p><h3 id="deep-agent-执行框架" tabindex="-1">Deep Agent：执行框架 <a class="header-anchor" href="#deep-agent-执行框架" aria-label="Permalink to &quot;Deep Agent：执行框架&quot;">​</a></h3><p>构建于 LangChain 与 LangGraph 之上，增加了规划能力、文件系统、子 Agent 等高级功能。核心能力：</p><ul><li><strong>显式规划</strong>：自主生成、执行并动态调整多步任务计划</li><li><strong>虚拟文件系统</strong>：为智能体提供结构化的中间结果与知识存储</li><li><strong>子智能体</strong>：支持任务在多个智能体之间分解与协作</li><li><strong>长期记忆</strong>：结合 LangGraph 状态存储，跨对话积累经验</li><li><strong>可扩展中间件</strong>：嵌入安全审计、性能监控或自定义业务逻辑</li></ul><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p011-%E5%AE%98%E6%96%B9%E6%96%87%E6%A1%A3%E4%B8%89%E8%80%85%E5%AF%B9%E6%AF%94.jpg" alt=""><em>图：官方文档给出的三者选择建议——想开箱即用地做智能体从 Deep Agents 起步，需要自己定制就用 LangChain，更复杂的确定性工作流编排上 LangGraph</em></p><h3 id="deep-agent-的定位补充" tabindex="-1">Deep Agent 的定位补充 <a class="header-anchor" href="#deep-agent-的定位补充" aria-label="Permalink to &quot;Deep Agent 的定位补充&quot;">​</a></h3><p>课程还专门交代了 Deep Agent 的定位与目标：</p><ul><li>它是<strong>新推出的全新组件</strong>，官方定位为 <strong>Agent Harness（智能体执行框架）</strong>；</li><li>它的目标：<strong>让开发者无须从零构建复杂的控制逻辑，即可创建具备深度规划、长期记忆与多专家协作能力的智能体</strong>；</li><li>顺带一句关系说明：三个框架<strong>不是竞争关系，并非互斥</strong>，复杂项目完全可以同时用到这三层。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>三者<strong>不是竞争关系</strong>：从 LangChain 快速搭建，用 LangGraph 打磨生产稳定性，再用 Deep Agent 赋予更强的自主能力——这才是完整的生态玩法。</p></div><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p011-%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E4%BD%93%E7%B3%BB%E5%9B%BE.jpg" alt=""><em>图：基于 LLM 的应用开发体系图——LangChain 打底（基础能力层），LangGraph 居中做高级编排，Deep Agent 在上层处理复杂任务</em></p><h3 id="langsmith-让智能体的运行过程可见" tabindex="-1">LangSmith：让智能体的运行过程可见 <a class="header-anchor" href="#langsmith-让智能体的运行过程可见" aria-label="Permalink to &quot;LangSmith：让智能体的运行过程可见&quot;">​</a></h3><p>单靠 print 调试已经不够用了。LangSmith 是官方的<strong>可视化监控与测试平台</strong>，跟踪、记录、分析智能体运行时的完整调用链路：</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>全链路追踪</td><td>可视化每一步的提示词、模型输出、工具使用</td></tr><tr><td>调试与优化</td><td>发现异常行为与性能瓶颈</td></tr><tr><td>评测与质量控制</td><td>支持人工与自动化评测</td></tr><tr><td>团队协作</td><td>共享测试集与调用记录</td></tr></tbody></table><p><img src="https://img.tsh520.cn/file/blog/article/ch01-p012-%E7%9B%91%E6%8E%A7%E7%9C%8B%E6%9D%BF%E7%95%8C%E9%9D%A2.jpg" alt=""><em>图：LangSmith 的监控看板——LLM 调用次数与成功/失败曲线、延迟分位数（P50/P99）、成本与 Token 消耗</em></p><h3 id="langsmith-官网与质量闭环" tabindex="-1">LangSmith 官网与质量闭环 <a class="header-anchor" href="#langsmith-官网与质量闭环" aria-label="Permalink to &quot;LangSmith 官网与质量闭环&quot;">​</a></h3><ul><li>LangSmith 官网：<a href="https://www.langchain.com/langsmith" target="_blank" rel="noreferrer">https://www.langchain.com/langsmith</a></li><li>课程对它的收尾评价：<strong>LangSmith 的引入使得智能体的开发、调试与运维形成了完整的质量闭环。</strong></li></ul><h2 id="开发前的前置知识" tabindex="-1">开发前的前置知识 <a class="header-anchor" href="#开发前的前置知识" aria-label="Permalink to &quot;开发前的前置知识&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>需要掌握</th></tr></thead><tbody><tr><td>Python 基础</td><td>变量、流程控制、函数与参数机制、<strong>类与对象、装饰器</strong>；常用容器、JSON、异常处理；模块导入、包管理、线程与协程</td></tr><tr><td>大模型基础</td><td>LLM、Token、Prompt、Embedding 的概念；用过豆包/千问/DeepSeek 等；了解 OpenAI/Anthropic/阿里云百炼/DeepSeek 等平台</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>这两块正是前面几章的内容——装饰器（函数进阶）、异常处理、JSON、面向对象（第 6 章）都会在 LangChain 里反复用到。</p></div><h3 id="langchain-生态支持-python-与-javascript" tabindex="-1">LangChain 生态支持 Python 与 JavaScript <a class="header-anchor" href="#langchain-生态支持-python-与-javascript" aria-label="Permalink to &quot;LangChain 生态支持 Python 与 JavaScript&quot;">​</a></h3><p>课程特意点明：<strong>LangChain 生态支持包括 Python 和 JavaScript 两种语言实现</strong>，其中 <strong>Python 版本仍是功能最完整、更新最及时、社区最活跃的核心实现</strong>——本课程讲的也是 Python 版。</p><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>Python 基础清单里的&quot;模块导入、<strong>包管理</strong>&quot;，课程推荐用 pip 或 conda——这正是下一篇《开发环境搭建（conda）》要动手做的事。</p></div><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/langchain学习笔记/02-大模型应用场景与技术选型/">大模型应用场景与技术选型</a></li><li><a href="/posts/编程学习/langchain学习笔记/03-开发环境搭建-conda/">开发环境搭建（conda）</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li>应用形态的三次跃迁：PC 互联网时代是<strong>传统应用</strong>，移动互联网时代是<strong>移动应用</strong>，AI 智能化时代是<strong>智能体</strong>；单一的大模型有四个局限：没有<strong>实时数据</strong>、会<strong>幻觉</strong>、不能操作<strong>外部系统</strong>、没有<strong>记忆</strong></li><li>LangChain 是大模型与应用之间的<strong>中间层</strong>；三大核心价值是统一的<strong>模型抽象层</strong>、高度<strong>模块化</strong>的设计、丰富的<strong>集成生态</strong>；课程把它比作智能体的<strong>操作系统内核</strong></li><li>六类典型场景：<strong>RAG（检索增强生成）</strong>（治知识滞后与幻觉）、<strong>Agent 智能体</strong>（把模型当&quot;推理引擎&quot;，自主规划并调用工具）、对话系统与聊天机器人（治多轮对话的&quot;记忆&quot;流失）、<strong>多模态应用</strong>（融合图像识别与语音转文字）、<strong>自动化写作与格式化生成</strong>（配合提示词模板与输出解析器）、<strong>数据连接与结构化处理</strong>（从 PDF/Excel 提取信息、自然语言转 SQL）</li><li>五层技术栈自下而上是：算力与<strong>Infra 基础设施</strong>层、海量数据与<strong>治理</strong>层、<strong>通用</strong>大模型层、行业/多模态应用大模型层、<strong>应用与（Agent）<strong>层，最上层对应的岗位是</strong>大模型与 Agent 应用开发工程师</strong>；应用与 Agent 层里还有一块&quot;Agents 编排与控制&quot;：LangChain <strong>流程图</strong>、LangGraph <strong>状态机</strong>、多 <strong>Agent</strong> 协作系统</li><li>发展时间线五个阶段：诞生 → <strong>探索期</strong> → <strong>体系化</strong> → 平台化 → <strong>深层智能体</strong>；诞生于 <strong>2022</strong> 年 <strong>10</strong> 月，创始人 <strong>Harrison Chase（哈里森·蔡斯）</strong> 当时的身份是哈佛大学的机器学习项目工程师，名字来自 Language + <strong>Chain</strong>；体系化阶段引入 Tool、Agent、Retrieval，形成&quot;大模型 + <strong>工具调用</strong> + <strong>记忆</strong>&quot;的核心架构；平台化阶段 <strong>LangGraph</strong> 为工作流管理提供了有向图基础、<strong>LangServe</strong> 解决了服务化部署的难题</li><li>v0.3 用 <code>initialize_agent</code> + AgentExecutor 构建 Agent，v1.2 的标准入口是 <code>create_agent</code>（底层基于 <strong>LangGraph</strong>）；工具定义上 v0.3 类型安全较弱，v1.2 支持 <strong>Pydantic Schema</strong> 定义工具；结构化输出在 v1.2 成了<strong>一等公民</strong>；扩展机制上 v1.2 有了 <strong>Middleware（中间件）</strong> 系统；1.x 把旧 Chain 类 API 迁到了 <code>langchain-classic</code> 包，并要求 Python &gt;= <strong>3.10</strong></li><li>版本对比：v0.3 无法无缝集成<strong>图像</strong>、<strong>音频</strong>等多模态数据，v1.2 <strong>完善</strong>了多模态适配；v0.3 只适合维护<strong>依赖 v0.3</strong> 的老项目，v1.2 是<strong>所有新项目和学习 LangChain</strong> 的首选版本；异步性能优化后响应速度提升 <strong>30%</strong> 以上</li><li>四大支柱：<strong>LangChain</strong>（基础能力层）、<strong>LangGraph</strong>（运行时编排层）、<strong>Deep Agent</strong>（智能体抽象层）、<strong>LangSmith</strong>（监控与评估层）；LangGraph 把智能体抽象成有向图，三要素是<strong>节点</strong>、<strong>边</strong>、<strong>状态</strong></li><li>Deep Agent 的官方定位是<strong>智能体执行框架</strong>（Agent Harness），五大能力是显式<strong>规划</strong>、虚拟<strong>文件系统</strong>、<strong>子智能体</strong>、长期<strong>记忆</strong>、可扩展<strong>中间件</strong>；LangSmith 是官方的<strong>可视化监控</strong>与<strong>测试</strong>平台，让智能体的开发、调试与运维形成完整的<strong>质量闭环</strong></li><li>前置知识：Python 侧的<strong>类与对象</strong>与<strong>装饰器</strong>会在 LangChain 里反复用到；大模型侧要掌握 LLM、<strong>Token</strong>、Prompt、<strong>Embedding</strong> 的概念；LangChain 生态同时支持 <strong>Python</strong> 和 <strong>JavaScript</strong> 两种语言，其中 <strong>Python</strong> 版本功能最完整、更新最及时</li></ol><h3 id="二、概念自测" tabindex="-1">二、概念自测 <a class="header-anchor" href="#二、概念自测" aria-label="Permalink to &quot;二、概念自测&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1 为什么需要 LangChain？</strong> 不用背课文：只说大模型自己干不了的那几件事，再说明 LangChain 分别在哪一层补上了缺口。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：先想&quot;一个光秃秃的大模型&quot;有哪些短板，再想每个短板要靠什么补 <strong>二级 · 角度</strong>：从&quot;数据从哪来&quot;&quot;怎么碰到外部世界&quot;&quot;多轮对话怎么记住&quot;三个角度各说一句 <strong>三级 · 骨架</strong>：四个短板 → 各自对应 LangChain 的哪块能力（外部数据源、工具集成、记忆管理、提示词与上下文）</p></details></li><li><p>[ ] <strong>2-2 LangChain 与 LangGraph 的分工</strong> 用&quot;有什么能力 / 怎么跑&quot;这组词讲清两者的分工，并说出图式结构相比链式调用多出来的三个关键词。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：一个是&quot;能力清单&quot;，一个是&quot;执行引擎&quot; <strong>二级 · 角度</strong>：从&quot;节点、边、状态&quot;三要素反推那三个关键词 <strong>三级 · 骨架</strong>：LangChain = ____抽象层；LangGraph = <strong><strong>与编排层；三个关键词 = 显式、可控、</strong></strong></p></details></li><li><p>[ ] <strong>2-3 版本辨认</strong> 网上抄到一段 2023 年的代码，里面的 Agent 构建入口和链式调用类都是 v0.3 那一套。你怎么判断它的版本？这套写法在 1.2 里还能直接用吗——不能的话，它们去哪了、现在该换成什么？</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：先认版本，再想 1.x 的&quot;官方标准入口&quot;是什么 <strong>二级 · 方法</strong>：<code>initialize_agent</code>、<code>AgentExecutor</code>、<code>LLMChain</code> 是 v0.3 的写法；1.x 里它们迁到了 <code>langchain-classic</code>，新入口是 <code>create_agent</code><strong>三级 · 骨架</strong>：判断依据 = 出现 <code>initialize_agent</code> / <code>AgentExecutor</code> → v0.3；替代 = <code>create_agent</code>（底层基于 LangGraph）</p></details></li><li><p>[ ] <strong>2-4 判断对错</strong> 判断下面三句话对不对，并各给一句理由： ① Deep Agent 出来之后 LangChain 就被替代了，新项目直接上 Deep Agent 就行； ② 学 LangChain 的正确姿势是先把所有 API 学完； ③ 接手一个 2023 年的老项目，第一件事是把它整体迁到 1.2。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：三句都在考&quot;官方建议&quot;，回到正文的结论句上 <strong>二级 · 角度</strong>：① 四大支柱之间是什么关系？② 官方把 LangChain 当工具箱还是教科书？③ 对比表里 v0.3 那一栏的&quot;推荐用途&quot;是怎么写的？ <strong>三级 · 骨架</strong>：① 不是竞争关系，几层可以同时用；② 只学核心逻辑与核心模块；③ 老项目的维护场景仍然可以留在 v0.3</p></details></li></ul><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-1</strong> 大模型自己做不到四件事：<strong>没有实时数据</strong>（训练数据是冻结的）、<strong>会幻觉</strong>（没学过的就编）、<strong>不能操作外部系统</strong>（查库、调 API、读文件都不行）、<strong>没有记忆</strong>（每次对话都是独立的）。LangChain 的活就是把这些短板接上：统一接口对接数据库/检索引擎/API/文件系统（外部数据）、封装工具调用与记忆等底层逻辑（工具与记忆）、管理提示词与上下文，再用 LangGraph 把单智能体扩展到多智能体协作。 <strong>2-2</strong> LangChain 是<strong>能力抽象层</strong>（有什么能力：把模型、消息、工具、中间件标准化）；LangGraph 是<strong>执行与编排层</strong>（怎么跑：把智能体抽象成有向图，用节点、边、状态表达分支与循环）。图式结构比链式调用多出来的三个关键词：<strong>显式</strong>（路径写在代码里看得见）、<strong>可控</strong>（分支与循环都能表达）、<strong>可观测</strong>（每一步的共享状态都留得下）。官方建议&quot;快速起步用 LangChain，复杂控制用 LangGraph，二者并行协同&quot;。 <strong>2-3</strong> 出现 <code>initialize_agent</code>、<code>AgentExecutor</code>（以及 <code>LLMChain</code>）这类写法，就是 <strong>v0.3</strong>（过渡版）的代码。这些 API 在 1.x 里已被移除，迁到了 <code>langchain-classic</code> 包，不能照抄到新项目里。1.x 的标准入口是 <strong><code>create_agent</code></strong>，底层基于 LangGraph。 <strong>2-4</strong> ① <strong>错</strong>。四大支柱是不同层次、<strong>并非互斥</strong>：LangChain 是基础能力层（相当于操作系统内核），LangGraph 负责复杂编排，Deep Agent 是上层的智能体执行框架（Agent Harness）。简单智能体用 LangChain 就够，需要复杂编排才上 LangGraph / Deep Agent。② <strong>错</strong>。官方原话是&quot;不要试图学完 LangChain 的所有 API&quot;——搞懂核心逻辑与核心模块，其它用到再查，把它当<strong>工具箱</strong>而不是教科书。③ <strong>错</strong>（更准确说是没必要）。v0.3 的推荐用途就是&quot;维护依赖 v0.3 的老旧项目&quot;，1.2 才是新项目的首选；老项目没有明确需求就不必为升级而升级，按 v0.3 的写法继续维护即可。</p></details>',109)])])}const u=n(g,[["render",s]]);export{p as __pageData,u as default};
